private val C0=Color(0xFF050912); private val C1=Color(0xFF0B1422); private val C2=Color(0xFF111D2D); private val CT=Color(0xFFF5F7FB); private val CM=Color(0xFF7F8DA3); private val CP=Color(0xFF8A45FF); private val CC=Color(0xFF26D9FF); private val CG=Color(0xFF21D79B); private val CR=Color(0xFFFF536F); private val CY=Color(0xFFFFC857)
