@Composable private fun Gauge(score:Int){Canvas(Modifier.size(125.dp)){for(i in 1..3)drawCircle(VBorder(),size.minDimension*.34f*i/3f,center,style=androidx.compose.ui.graphics.drawscope.Stroke(1f));drawCircle(if(score>=70)CR else CP,size.minDimension*.18f,center);drawCircle(CC,size.minDimension*.34f,center,style=androidx.compose.ui.graphics.drawscope.Stroke(2f))}}
@Composable private fun Equity(v:List<Double>,m:Modifier){Canvas(m){if(v.size<2)return@Canvas;val min=v.minOrNull()?:0.0;val max=v.maxOrNull()?:1.0;val r=(max-min).takeIf{it>0}?:1.0;for(i in 1 until v.size){val x1=size.width*(i-1)/v.lastIndex;val x2=size.width*i/v.lastIndex;val y1=size.height-((v[i-1]-min)/r*size.height).toFloat();val y2=size.height-((v[i]-min)/r*size.height).toFloat();drawLine(CP,Offset(x1,y1),Offset(x2,y2),2f)}}}
@Composable private fun Spark(v:List<Double>,m:Modifier){Canvas(m){if(v.size<2)return@Canvas;val min=v.minOrNull()?:0.0;val max=v.maxOrNull()?:1.0;val r=(max-min).takeIf{it>0}?:1.0;var last=Offset(0f,size.height);v.forEachIndexed{i,x->val p=Offset(size.width*i/(v.lastIndex.toFloat()),size.height-((x-min)/r*size.height).toFloat());if(i>0)drawLine(CC,last,p,2f);last=p}}}
private fun VBorder()=Color(0xFF1B2B3D)
private fun money(v:Double)=if(v>=1000)"%,.2f".format(v)else if(v>=1)"%.4f".format(v)else"%.8f".format(v)
private fun pct(v:Double)="%+.2f%%".format(v)
private fun compact(v:Double)=when{v>=1e9->"%.1fB".format(v/1e9);v>=1e6->"%.1fM".format(v/1e6);v>=1e3->"%.1fK".format(v/1e3);else->"%.0f".format(v)}
